TLM.f("Sancti/09-26",{"officium":"Ss. Cypriani et Justinæ Martyrum","rule":["vide C3;","Gloria"],"fallback":"Commune/C3b","from":{"Introitus":"Commune/C3b","Lectio":"Commune/C3b","Graduale":"Commune/C3b","Tractus":"Commune/C3b","Evangelium":"Commune/C3b","Offertorium":"Commune/C3b","Communio":"Commune/C3b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:39"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."}],"Oratio":[{"k":"text","la":"Sanctórum Mártyrum tuórum Cypriáni et Iustínae nos, Dómine, fóveant continuáta praesídia: quia non désinis propítius intuéri; quos tálibus auxíliis concésseris adiuvári."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 10:32-38"},{"k":"text","la":"Fratres: Rememorámini prístinos dies, in quibus illumináti magnum certámen sustinuístis passiónum: et in áltero quidem oppróbriis et tribulatiónibus spectáculum facti: in áltero autem sócii táliter conversántium effécti. Nam et vinctis compássi estis, et rapínam bonórum vestrórum cum gáudio suscepístis, cognoscéntes vos habere meliórem et manéntem substántiam. Nolíte itaque amíttere confidéntiam vestram, quæ magnam habet remuneratiónem. Patiéntia enim vobis necéssaria est: ut, voluntátem Dei faciéntes, reportétis promissiónem. Adhuc enim módicum aliquántulum, qui ventúrus est, véniet, et non tardábit. Justus autem meus ex fide vivit."}],"Graduale":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:1-8"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Atténdite a ferménto pharisæórum, quod est hypócrisis. Nihil autem opértum est, quod non revelétur: neque abscónditum, quod non sciátur. Quóniam, quæ in ténebris dixístis, in lúmine dicéntur: et quod in aurem locúti estis in cubículis, prædicábitur in tectis. Dico autem vobis amícis meis: Ne terreámini ab his, qui occídunt corpus, et post hæc non habent ámplius quid fáciant. Osténdam autem vobis, quem timeátis: timéte eum, qui postquam occíderit, habet potestátem míttere in gehénnam. Ita dico vobis: hunc timéte. Nonne quinque pásseres véneunt dipóndio, et unus ex illis non est in oblivióne coram Deo? Sed et capílli cápitis vestri omnes numeráti sunt. Nolíte ergo timére: multis passéribus pluris estis vos. Dico autem vobis: Omnis, quicúmque conféssus fúerit me coram homínibus, et Fílius hóminis confitébitur illum coram Angelis Dei."}],"Offertorium":[{"k":"ref","la":"Sap 3:1-3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiae: visi sunt óculis insipiéntium mori: illi autem sunt in pace, allelúja."}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, nostra devotiónis offérimus: quæ et pro tuórum tibi grata sint honóre Justórum, et nobis salutária, te miseránte, reddántur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 10:27"},{"k":"text","la":"Quod dico vobis in ténebris, dícite in lúmine, dicit Dóminus: et quod in aure audítis, prædicáte super tecta."}],"Postcommunio":[{"k":"text","la":"Præsta nobis, quǽsumus, Dómine: intercedéntibus sanctis Martýribus tuis Cypriáno et Justína; ut, quod ore contíngimus, pura mente capiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ce4afac6809731f0":{"t":"<i>Pomolimo se</i>.\nNeka nas pomogne, Gospodine, neprestana zaštita svetih mučenika tvojih Ciprijana i Justine, jer ne prestaješ milostivo gledati na one koje na takav način pomažeš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bila uvijek uz nas, Gospodine, zaštita blaženih mučenika Tvojih Ciprijana i Justine, jer ne prestaješ blago gledati na one, kojima dopuštaš ovoliku pomoć, po G, n.","knRef":"Kniewald 1942, str. 718–719 (snimka 360) (OCR)"},"0b5f9e55c57d534d":{"t":"Prikazujemo ti, Gospodine, darove svoje odanosti, da ti budu mili zbog časti tvojih pravednika, a nama postanu spasonosni po tvom milosrđu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prikazujemo Ti, Gospodine, darove naše poboznosti moleći Te, da. Tebi budu dragi poradi časti Tvojih pravednika, a nama da po Tvome milosrđu budu spasonasniji, (po G. n.","knRef":"Kniewald 1942, str. 488–489 (snimka 245) (OCR)"},"e7d36b1ccee29b64":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, Gospodine, po zagovoru svojih svetih mučenika Ciprijana i Justine da čistom dušom prihvatimo što smo ustima primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, molimo, Gospodine, da zagovorom Tvojih svetih mučenika Ciprijana i Justine prihvatimo čistom dušom, što ustima primamo, po G. n.","knRef":"Kniewald 1942, str. 718–719 (snimka 360) (OCR)"}}});
